"""Self-contained synthetic evidence-review view; no CDN or external requests."""
import json
from pathlib import Path


def write_report(run, path: Path):
    payload = {"run_id": run["run_id"], "as_of": run["request"]["as_of"],
               "patients": run["coverage"]["evaluated"], "coverage": run["coverage"],
               "agere": run["agere"], "telemetry": run["telemetry"]}
    safe = json.dumps(payload).replace("<", "\\u003c").replace("&", "\\u0026")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(PAGE.replace("__PAYLOAD__", safe))


PAGE = r'''<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Agere · Evidence intelligence</title>
<style>
:root{--ink:#183330;--muted:#546b64;--line:#d5dfd5;--green:#136853;--paper:#f4f5ed;--amber:#795a12}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 ui-sans-serif,system-ui,sans-serif}
header{display:flex;justify-content:space-between;align-items:center;padding:23px 5vw;border-bottom:1px solid var(--line)}
.brand{font-size:28px;letter-spacing:-1.7px;font-weight:650}.pill{font:11px ui-monospace,monospace;letter-spacing:1px;border:1px solid #9aaea0;padding:7px 10px;border-radius:20px}
main{max-width:1440px;margin:auto;padding:46px 5vw}h1{font:clamp(35px,4.4vw,64px)/1.06 Georgia,serif;letter-spacing:-2px;margin:12px 0 20px;max-width:920px;font-weight:400}
.eyebrow{text-transform:uppercase;letter-spacing:2px;font-size:11px;font-weight:650;color:var(--green)}.lede{color:var(--muted);max-width:790px;font-size:17px}.flow{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:30px 0;color:var(--muted);font-size:13px}.flow span{border-bottom:2px solid #b9ccc1;padding:6px 0}.flow span:last-child{border-color:var(--green);color:var(--green)}
.metrics{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--line);background:#fffefa;margin:25px 0 40px}.metric{padding:20px;border-right:1px solid var(--line)}.metric:last-child{border:0}.metric b{display:block;font-size:32px;font-weight:500;letter-spacing:-1px}.metric span{color:var(--muted);font-size:12px}
.workspace{display:grid;grid-template-columns:230px minmax(0,1fr);gap:32px}.tabs{display:flex;flex-direction:column;gap:7px}button,input,select{font:inherit}button{cursor:pointer}.tab{border:1px solid transparent;background:transparent;color:var(--ink);border-radius:7px;text-align:left;padding:11px;display:flex;justify-content:space-between;gap:12px}.tab[aria-pressed=true]{background:var(--ink);color:white}.tab:hover{border-color:#91a99b}.tab small{opacity:.75}.aside-note{font-size:12px;color:var(--muted);margin-top:24px;border-top:1px solid var(--line);padding-top:18px}
.toolbar{display:flex;gap:10px;margin-bottom:15px;flex-wrap:wrap}.toolbar input,.toolbar select{background:#fffefa;border:1px solid var(--line);border-radius:6px;padding:11px;min-width:0}.toolbar input{flex:1}.count{font-size:12px;color:var(--muted);margin-bottom:12px}.card{background:#fffefa;border:1px solid var(--line);border-radius:9px;margin-bottom:12px;overflow:hidden}.card summary{list-style:none;cursor:pointer;padding:20px}.card summary::-webkit-details-marker{display:none}.card summary:focus-visible,button:focus-visible{outline:3px solid #b87c13;outline-offset:3px}.identity{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:12px;color:var(--muted)}.identity b{color:var(--ink);font:13px ui-monospace,monospace}.title{font-size:21px;letter-spacing:-.5px;margin:9px 0}.action{color:var(--muted);max-width:800px;font-size:14px}.badge{font-size:11px;padding:4px 8px;background:#e5eee5;border-radius:4px;display:inline-block;margin-top:12px}.badge.warn{background:#f4ebcc;color:#66501f}.expand{font-size:12px;color:var(--green);display:block;margin-top:13px}.detail{padding:0 20px 22px;border-top:1px solid var(--line)}.detail h3{font-size:12px;letter-spacing:1px;text-transform:uppercase;margin-top:24px}blockquote{margin:10px 0;background:#f1f4eb;border-left:3px solid #7b9a85;padding:14px;font-size:14px;white-space:pre-wrap}.source{font:11px/1.6 ui-monospace,monospace;overflow-wrap:anywhere;color:var(--muted)}.evidence{padding:8px 0 15px;border-bottom:1px solid var(--line)}.coverage{padding:9px 0;border-bottom:1px solid var(--line);font-size:13px}.detail li{font-size:13px;margin:7px 0}.empty{padding:35px;border:1px dashed var(--line)}#more{border:1px solid var(--line);padding:12px 20px;background:white;border-radius:6px}footer{border-top:1px solid var(--line);padding:24px 5vw;color:var(--muted);font-size:12px;overflow-wrap:anywhere}
@media(max-width:800px){main{padding:30px 5vw}.workspace{grid-template-columns:1fr}.tabs{flex-direction:row;flex-wrap:wrap}.tab{font-size:12px}.aside-note{margin-top:12px}.metrics{grid-template-columns:repeat(2,1fr)}.metric{border-bottom:1px solid var(--line)}h1{letter-spacing:-1px}.toolbar select{width:100%}}
</style>
<header><div class="brand">agere<span style="color:#4d9773">.</span></div><span class="pill">SYNTHETIC RESEARCH · LOCAL</span></header>
<main><div class="eyebrow">Evidence intelligence / first working slice</div><h1>Understand the care.<br>Understand what you cannot see.</h1>
<p class="lede">An empty field can hide outside care, an appropriate hold, an access barrier—or care that never happened. Agere separates the evidence from the uncertainty, then identifies what to clarify next.</p>
<div class="flow"><span>Fragmented records</span> → <span>Dated evidence</span> → <span>Care + source coverage</span> → <span>A supported next step</span></div>
<div class="metrics" id="metrics"></div><div class="workspace"><aside><div class="eyebrow" style="margin-bottom:14px">Review by evidence state</div><nav class="tabs" id="tabs" aria-label="Evidence state"></nav><div class="aside-note">These are patient–subject assessments, not confirmed care gaps. The current reader is a synthetic lexicon baseline. No automatic outreach or calibrated clinical probabilities.<p>Source coverage is unknown unless explicitly supplied. More records do not establish completeness.</p></div></aside>
<section aria-label="Patient evidence"><div class="toolbar"><input id="search" aria-label="Search patient or subject" placeholder="Search patient or subject…"><select id="practice" aria-label="Filter practice"><option value="">All practices</option></select></div><div class="count" id="count" aria-live="polite"></div><div id="cards"></div><button id="more" hidden>Show more assessments</button></section></div></main><footer id="footer"></footer>
<script type="application/json" id="data">__PAYLOAD__</script>
<script>
const data=JSON.parse(document.getElementById('data').textContent),all=data.agere.items;
const labels={access_review:'Documented barriers',exception_review:'Holds & intolerance',reconcile_timeline:'Reconcile the timeline',outside_record_reconciliation:'Reported outside care',transaction_review:'Unresolved transactions',insufficient_evidence:'Missing evidence',care_record_observed:'Care records observed'};
const subjectNames={mra:'MRA',sglt2:'SGLT2',arni:'ARNI',bb:'Beta blocker',statin:'Statin',a1c:'HbA1c'};
let state='',limit=40;const $=id=>document.getElementById(id);
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
for(const [number,label] of [[data.patients,'Synthetic patients supplied'],[data.agere.patient_subject_pairs,'Patient–subject assessments'],[data.agere.states.insufficient_evidence||0,'Questions with insufficient evidence'],[data.telemetry.external_model_calls??'—','External model calls in this run']]){const m=el('div',undefined,'metric');m.append(el('b',number.toLocaleString()),el('span',label));$('metrics').append(m)}
const tabButtons=[];for(const [key,label] of [['','All assessments'],...Object.entries(labels)]){const b=el('button',undefined,'tab');b.type='button';b.append(el('span',label),el('small',key?(data.agere.states[key]||0):all.length));b.setAttribute('aria-pressed',key===state);b.onclick=()=>{state=key;limit=40;for(const [k,x]of tabButtons)x.setAttribute('aria-pressed',k===state);render()};tabButtons.push([key,b]);$('tabs').append(b)}
for(const p of Object.keys(data.agere.by_practice)){const o=el('option',p);o.value=p;$('practice').append(o)}
function detail(a){const d=el('div',undefined,'detail');d.append(el('h3','What the available record supports'));
if(!a.evidence.length)d.append(el('p','No qualifying evidence was found by this reader in the research window. This does not establish that care was absent.'));
for(const e of a.evidence){const block=el('div',undefined,'evidence');block.append(el('p',e.kind.replaceAll('_',' ')),el('div',`${e.event_date} · ${e.event_date_basis.replaceAll('_',' ')} · arrival: ${e.available_date||'unknown'}`,'source'));if(e.reference.antecedent)block.append(el('blockquote','Preceding context: '+e.reference.antecedent.quote));block.append(el('blockquote',e.reference.quote||JSON.stringify(e.detail)));block.append(el('div',`${e.reference.source} / ${e.reference.record_id} · offsets ${e.reference.start??'n/a'}–${e.reference.end??'n/a'}`,'source'),el('div','Source SHA-256: '+e.reference.source_hash,'source'));d.append(block)}
d.append(el('h3','What we can see'));for(const c of a.observability)d.append(el('div',`${c.source}: ${c.status.replaceAll('_',' ')}. ${c.reason}`,'coverage'));
d.append(el('h3','What remains uncertain'));const ul=el('ul');for(const u of a.unknowns)ul.append(el('li',u));d.append(ul);d.append(el('h3','Next information needed'));const needs=el('ul');for(const n of a.information_needs)needs.append(el('li',`${n.source}: ${n.reason}`));if(!a.information_needs.length)needs.append(el('li','No additional source request selected by this baseline. Clinical review may still be needed.'));d.append(needs,el('p',`Research window ${a.window_start} through ${a.as_of}. These dates do not define clinical due dates.`,'source'),el('p','Assessment snapshot: '+a.assessment_snapshot,'source'));return d}
function render(){const q=$('search').value.toLowerCase(),p=$('practice').value;const filtered=all.filter(a=>(!state||a.state===state)&&(!p||a.practice===p)&&(`${a.patient_id} ${a.subject} ${subjectNames[a.subject]}`).toLowerCase().includes(q));$('cards').replaceChildren();$('count').textContent=`${filtered.length.toLocaleString()} assessments · showing ${Math.min(limit,filtered.length)} · data cutoff ${data.as_of}`;if(!filtered.length)$('cards').append(el('div','No matching assessments.','empty'));for(const a of filtered.slice(0,limit)){const card=el('details',undefined,'card'),s=el('summary'),identity=el('div',undefined,'identity');identity.append(el('b',a.patient_id),el('span',a.practice));s.append(identity,el('div',`${subjectNames[a.subject]||a.subject} · ${labels[a.state]}`,'title'),el('div',a.next_action,'action'),el('span',`${a.evidence.length} evidence assertions · coverage ${a.observability.every(c=>c.status==='complete_for_scope')?'declared for scope':'incomplete or unknown'}`,'badge'+(a.state==='insufficient_evidence'?' warn':'')),el('span','Inspect evidence and uncertainty ↓','expand'));card.append(s);card.addEventListener('toggle',()=>{if(card.open&&!card.dataset.loaded){card.append(detail(a));card.dataset.loaded='true'}});$('cards').append(card)}$('more').hidden=filtered.length<=limit}
$('search').oninput=()=>{limit=40;render()};$('practice').onchange=()=>{limit=40;render()};$('more').onclick=()=>{limit+=40;render()};$('footer').textContent=`Synthetic research only. No real patient records. Evidence matching is not clinical validation. Run ${data.run_id}`;render();
</script></html>'''
